import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';

/// ============================================================
/// IVORY - THE GOLDEN FEATHER (the owner's own artwork)
///
/// CC.216: the feather on the story door is the owner's golden
/// feather itself, carried inside the app as bytes - not a vendor
/// emoji (every phone brand draws those differently), not a painted
/// guess, not an asset file to upload. The same strokes on every
/// Android brand, version and fork, forever: nib low-left, tip
/// high-right, exactly as she drew it.
/// ============================================================
class GoldenQuill {
  const GoldenQuill._();

  static const String _b64 = '';

  static Uint8List? _bytes;

  /// The feather's own bytes, decoded once and remembered.
  static Uint8List get bytes => _bytes ??= base64Decode(_b64);

  /// The feather at any width, keeping its own proportions.
  static Widget show(double width) => Image.memory(
        bytes,
        width: width,
        height: width * 100 / 96,
        fit: BoxFit.contain,
        gaplessPlayback: true,
      );
}

